module freq_div (
    input CLK_in,
    output reg CLK_50,
    output reg CLK_10,
    output reg CLK_1,
    input RST
);

reg [7:0] cnt_50;
reg [7:0] cnt_10;
reg [7:0] cnt_1;

always @(posedge CLK_in or posedge RST) begin
    if (RST) begin
        cnt_50 <= 8'b0;
        cnt_10 <= 8'b0;
        cnt_1 <= 8'b0;
        CLK_50 <= 1'b0;
        CLK_10 <= 1'b0;
        CLK_1 <= 1'b0;
    end else begin
        cnt_50 <= ~cnt_50;
        cnt_10 <= ~cnt_10;
        cnt_1 <= ~cnt_1;
        CLK_50 <= cnt_50[7];
        CLK_10 <= cnt_10[7];
        CLK_1 <= cnt_1[7];
    end
end

endmodule
